PREFIX brick: <http://brickschema.org/schema/brick#>
SELECT ?z ?label ?zoneclass WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label . }
  BIND(STR(?z) AS ?zoneclass)
} LIMIT 100

PREFIX brick: <http://brickschema.org/schema/brick#>
SELECT ?z WHERE {
  ?z a brick:Zone .
} LIMIT 100

